<script setup>
import { reactive } from 'vue';
const props = defineProps({ initialRepairment: { type: Object, default: () => ({}) }, busy: Boolean, submitLabel: { type: String, default: 'Save repairment' }, suggestions: { type: Object, default: () => ({}) } });
const emit = defineEmits(['submit', 'cancel']);
const form = reactive({ status: props.initialRepairment.status || 'repairing', serial_num: props.initialRepairment.serial_num || '', delivered_to: props.initialRepairment.delivered_to || '', delivered_by: props.initialRepairment.delivered_by || '', field_test_date: (props.initialRepairment.field_test_date || []).join(', '), repairer: (props.initialRepairment.repairer || []).join(', '), spare_part: (props.initialRepairment.spare_part || []).map((p) => `${p.part}:${p.price}`).join(', '), update: '' });
function addToday() { form.field_test_date = [...form.field_test_date.split(',').map((v) => v.trim()).filter(Boolean), new Date().toISOString()].join(', '); }
function submit() { if (!form.status) return; emit('submit', { status: form.status, serial_num: form.serial_num.trim(), delivered_to: form.delivered_to.trim() || undefined, delivered_by: form.delivered_by.trim() || undefined, field_test_date: form.field_test_date.split(',').map((v) => v.trim()).filter(Boolean), repairer: form.repairer.split(',').map((v) => v.trim()).filter(Boolean), spare_part: form.spare_part.split(',').map((v) => { const [part, price] = v.split(':'); return { part: part.trim(), price: Number(price) || 0 }; }).filter((v) => v.part), updates: form.update.trim() ? [{ text: form.update.trim() }] : undefined }); }
</script>
<template><form class="item-form" @submit.prevent="submit"><section class="form-section"><span class="eyebrow">Repairment record</span><h2>Track this unit’s repair</h2><div class="field-grid"><label class="field"><span>Serial number</span><input v-model="form.serial_num" name="serial_num" list="repairment-serial-num-options"></label><label class="field"><span>Status *</span><select v-model="form.status" name="status" required><option value="repairing">Repairing</option><option value="awaiting_spare_part">Awaiting spare part</option><option value="repaired">Repaired</option><option value="unrepairable">Unrepairable</option><option value="delivered">Delivered</option></select></label></div><div v-if="form.status === 'delivered'" class="field-grid"><label class="field"><span>Delivered to *</span><input v-model="form.delivered_to" name="delivered_to" list="repairment-delivered-to-options" required></label><label class="field"><span>Delivered by</span><input v-model="form.delivered_by" name="delivered_by" list="repairment-delivered-by-options"></label></div><label class="field"><span>Field test dates</span><div class="input-with-action"><input v-model="form.field_test_date" name="field_test_date"><button type="button" class="button button--ghost" @click="addToday">Add today</button></div></label><label class="field"><span>Repairers</span><input v-model="form.repairer" name="repairer" list="repairment-repairer-options"></label><label class="field"><span>Spare parts</span><input v-model="form.spare_part" name="spare_part" list="repairment-spare-part-options"></label><label class="field"><span>Add update note</span><textarea v-model="form.update" name="update" rows="3"></textarea></label><datalist v-for="field in ['serial_num', 'delivered_to', 'delivered_by', 'repairer', 'spare_part']" :id="`repairment-${field.replaceAll('_', '-')}-options`" :key="field"><option v-for="value in suggestions[field] || []" :key="value" :value="value" /></datalist></section><div class="form-actions"><button v-if="$attrs.onCancel" type="button" class="button button--ghost" @click="$emit('cancel')">Cancel</button><button class="button button--primary" :disabled="busy">{{ busy ? 'Saving…' : submitLabel }}</button></div></form></template>
